{"op":"begin","version":1,"title":"二维交互示例","state":{"count":0,"speed":1}}
{"op":"node","node":{"id":"canvas","kind":"web","data":"{\"version\":1,\"library\":\"none\",\"height\":360,\"html\":\"<canvas id=\\\"stage\\\"></canvas><section><button id=\\\"add\\\">计数 +1</button><strong id=\\\"count\\\"></strong><label>动画速度 <input id=\\\"speed\\\" type=\\\"range\\\" min=\\\"0\\\" max=\\\"3\\\" step=\\\"0.1\\\"></label><p id=\\\"status\\\">点击计数或调整速度，验证状态回传</p></section>\",\"css\":\"body{background:#f5f8f6}canvas{width:100%;height:180px}section{padding:16px;display:grid;gap:12px}button{background:#d9eee3;border:0;border-radius:12px;color:#175345}label{display:flex;justify-content:space-between;gap:12px}p{margin:0;font-size:13px}\",\"js\":\"const canvas=document.getElementById('stage'),ctx=canvas.getContext('2d');\\nif(!ctx)throw new Error('Canvas 2D 不可用');\\nconst add=document.getElementById('add'),count=document.getElementById('count'),speed=document.getElementById('speed'),status=document.getElementById('status');let state=tinybot.state,angle=0;\\nfunction apply(values){state=values;count.textContent='当前计数：'+values.count;speed.value=values.speed;add.disabled=!tinybot.active;speed.disabled=!tinybot.active;}\\napply(state);tinybot.onState(apply);\\nasync function save(patch){try{apply(await tinybot.save({...tinybot.state,...patch}));status.textContent='状态已保存';}catch(error){status.textContent=error.message;}}\\nadd.onclick=()=>save({count:tinybot.state.count+1});speed.onchange=()=>save({speed:Number(speed.value)});\\nfunction paint(){const w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);ctx.save();ctx.translate(w/2,h/2);ctx.rotate(angle);ctx.fillStyle='#54a98a';ctx.fillRect(-40,-40,80,80);ctx.restore();}\\nnew ResizeObserver(()=>{canvas.width=canvas.clientWidth;canvas.height=canvas.clientHeight;paint();}).observe(canvas);\\ntinybot.animate((time,delta)=>{angle+=state.speed*delta;paint();});\"}"}}
